/* Cross-role design preview. No API calls; all people, decisions and dates are illustrative. */
const DOMAINS=['Data and information','Communication','Digital content','Safety','Problem solving','AI literacy'];
const SHORT=['Data','Collaboration','Content','Safety','Problem solving','AI'];
const LEVELS=['Outside path','Basic','Intermediate','Advanced'];
const VIEWS=[['trial','01','Free trial'],['blueprint','02','Blueprint'],['people','03','People'],['gap','04','Capability'],['learning','05','Learning'],['review','06','Manager review']];
const embeddedFlow=new URLSearchParams(location.search).has('embed');
const flowStorageKey='pulse-unified-operating-flow-v1';
const makeDept=(name,caps,positions,manager)=>({name,caps,positions,manager});
const model={
  view:'trial',enterprise:[3,3,2,2,2,1],platform:[3,3,3,3,3,3],published:true,dirty:false,
  departments:[
    makeDept('Accounting',[3,2,2,2,2,1],[{name:'Accountant',targets:[3,2,1,2,2,0]},{name:'Finance Lead',targets:[3,2,2,2,2,1]}],'Nora Park'),
    makeDept('Marketing',[2,3,2,2,2,1],[{name:'Marketing Specialist',targets:[2,3,2,2,2,1]},{name:'Growth Analyst',targets:[2,3,2,2,2,1]}],'Jordan Lee'),
    makeDept('Sales',[2,3,1,2,2,1],[{name:'Sales (CRM)',targets:[2,3,1,2,2,1]}],'Minh Pham')
  ],
  selectedDept:0,selectedPosition:0,selectedEmployee:0,selectedDomain:0,gapScope:'employee',managerDept:0,
  employees:[
    {name:'Mia Nguyen',email:'mia@northstar.example',dept:'Accounting',position:'Accountant',current:[1,1,1,2,1,0],source:'Baseline assessment · 10 Oct'},
    {name:'Alex Tran',email:'alex@northstar.example',dept:'Sales',position:'Sales (CRM)',current:[2,1,1,2,1,0],source:'Baseline assessment · 10 Oct'},
    {name:'Ava Le',email:'ava@northstar.example',dept:'Marketing',position:'Marketing Specialist',current:[1,2,1,2,1,0],source:'Baseline assessment · 11 Oct'},
    {name:'Ben Dao',email:'ben@northstar.example',dept:'Accounting',position:'Accountant',current:[1,1,0,1,1,0],source:'Baseline assessment · 11 Oct'},
    {name:'Ella Vo',email:'ella@northstar.example',dept:'Marketing',position:'Growth Analyst',current:[1,1,1,2,1,0],source:'Baseline assessment · 11 Oct'},
    {name:'Noah Bui',email:'noah@northstar.example',dept:'Sales',position:'Sales (CRM)',current:[1,1,1,2,1,0],source:'Baseline assessment · 11 Oct'},
    {name:'Ivy Pham',email:'ivy@northstar.example',dept:'Accounting',position:'Finance Lead',current:[2,1,1,2,1,0],source:'Baseline assessment · 11 Oct'}
  ],
  pendingEmployees:1,managers:['Nora Park','Jordan Lee','Minh Pham'],
  proposals:[{id:1,dept:'Marketing',domain:0,requested:3,reason:'The analytics role needs a stronger data ceiling.',by:'Jordan Lee',status:'pending'}],
  assignment:{employee:'Mia Nguyen',dept:'Accounting',course:'Data and information · Basic',attempts:0,status:'ready',feedback:'',releaseAt:null,dueAt:null,flagged:false},
  queue:[
    {id:'mia',employee:'Mia Nguyen',dept:'Accounting',position:'Accountant',course:'Data and information · Basic',attempts:0,status:'ready',submitted:'—'},
    {id:'ben',employee:'Ben Dao',dept:'Accounting',position:'Accountant',course:'Data and information · Basic',attempts:1,status:'pending',submitted:'Today'},
    {id:'ava',employee:'Ava Le',dept:'Marketing',position:'Marketing Specialist',course:'Digital content · Basic',attempts:2,status:'pending',submitted:'Today'},
    {id:'alex',employee:'Alex Tran',dept:'Sales',position:'Sales (CRM)',course:'Communication · Basic',attempts:2,status:'flagged',submitted:'Yesterday'}
  ],
  selectedSubmission:'ben',decision:'pass',cooldownHours:48,deadlineDays:7,nowOffsetHours:0,
  signupDone:false,importRows:null,importFilename:'',importError:'',pendingEmails:[],notice:''
};
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const fmtLevel=n=>n===0?'Outside path':`L${n} · ${LEVELS[n]}`;
const badge=(text,tone='blue')=>`<span class="of-badge ${tone}">${text}</span>`;
const button=(text,action,kind='primary',extra='')=>`<button type="button" class="of-button ${kind}" data-action="${action}" ${extra}>${text}</button>`;
const dept=()=>model.departments[model.selectedDept];
const position=()=>dept().positions[model.selectedPosition]||dept().positions[0];
const employee=()=>model.employees[model.selectedEmployee];
const employeeDept=person=>model.departments.find(d=>d.name===person.dept);
const employeePosition=person=>employeeDept(person)?.positions.find(p=>p.name===person.position);
const assignedCount=()=>model.employees.length+model.pendingEmployees;
const now=()=>Date.now()+model.nowOffsetHours*3600000;
const hoursLeft=stamp=>Math.max(0,Math.ceil((stamp-now())/3600000));
function toast(message){model.notice=message;const el=$('#of-toast');if(el){el.textContent=message;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,4500)}}
function navigate(view){if(!VIEWS.some(v=>v[0]===view))view='trial';model.view=view;if(embeddedFlow){saveEmbeddedFlow();window.parent.postMessage({type:'pulse-operating-route',view},'*');return}history.pushState(null,'',`#${view}`);render();window.scrollTo({top:0,behavior:'instant'})}
function saveEmbeddedFlow(){if(!embeddedFlow)return;try{sessionStorage.setItem(flowStorageKey,JSON.stringify(model))}catch{}window.parent.postMessage({type:'pulse-operating-state',state:model},'*')}
function restoreEmbeddedFlow(){if(!embeddedFlow)return;try{const saved=JSON.parse(sessionStorage.getItem(flowStorageKey)||'null');if(saved&&Array.isArray(saved.departments)&&Array.isArray(saved.employees))Object.assign(model,saved)}catch{}}
function reportEmbeddedHeight(){if(embeddedFlow)window.parent.postMessage({type:'pulse-operating-height',height:document.documentElement.scrollHeight},'*')}
function applyEmbeddedRole(){if(!embeddedFlow)return;const role=new URLSearchParams(location.search).get('role');if(role==='manager'&&['gap','review'].includes(model.view))model.managerDept=0;if(model.view!=='gap')return;model.gapScope=role==='manager'?'manager':'owner';if(model.gapScope==='manager'&&employee().dept!==model.departments[model.managerDept].name){const index=model.employees.findIndex(x=>x.dept===model.departments[model.managerDept].name);if(index>=0)model.selectedEmployee=index}}
function refresh(){const y=window.scrollY;render();window.scrollTo({top:y,behavior:'instant'})}
function note(text){return `<div class="of-note">${text}</div>`}
function heading(kicker,title,summary,aside=''){return `<div class="of-heading"><div><span class="of-kicker">${kicker}</span><h1>${title}</h1><p>${summary}</p></div>${aside}</div>`}
function nav(){return `<div class="of-preview">PULSE / OPERATING FLOW · DESIGN PREVIEW · SAMPLE DATA <a href="06-pulse-flow-studio.html#home">63-screen gallery ↗</a></div><header class="of-header"><div class="of-header-inner"><a class="of-brand pulse-brand" href="#trial" data-view="trial"><img class="pulse-mark" src="assets/pulse-mark.svg" alt=""><span class="pulse-wordmark">DigiTalent <span class="pulse-name">Pulse</span></span><small>Enterprise flow</small></a><nav class="of-nav" aria-label="Operating flow">${VIEWS.map(([id,no,title])=>`<a href="#${id}" data-view="${id}" class="${model.view===id?'active':''}"><span>${no}</span>${title}</a>`).join('')}</nav><div class="of-header-status">${badge('FREE TRIAL','lime')}<small>10 Employee seats · no expiry</small></div></div></header>`}
function frame(content){return `${nav()}<main class="of-main">${content}</main><footer class="of-footer"><span>DigiTalent Pulse · Reviewable operating flow</span><span>Illustrative content · no product data changed</span></footer><div class="of-toast" id="of-toast" role="status" hidden></div>`}

function trialPage(){return `${heading('01 / SELF-SERVICE TRIAL','Start without waiting for approval.','A business verifies its email, enters the workspace, then builds a capability blueprint before inviting a Manager or Employee.',`<div class="of-hero-art"><img src="assets/competency-architecture.png" alt="Abstract glass competency architecture"></div>`)}
 <div class="of-trial-hero"><div class="of-trial-intro"><span class="of-kicker">PHASE I · FREE BASIC</span><h2>Learn first. Decide what grows next.</h2><p>Every Basic course can be viewed and studied. The trial has no calendar end date. Employee seats are shared across all departments; Owner and Manager accounts do not use them.</p><form id="of-register-form" class="of-register-form"><label>Business name<input name="business" required placeholder="Northstar Studio"></label><label>Owner work email<input name="email" type="email" required placeholder="owner@business.com"></label><button class="of-button primary" type="submit">${model.signupDone?'Open your blueprint →':'Create preview workspace →'}</button></form><div class="of-hero-actions">${button('See the access rules','rules','secondary')}</div><small class="of-register-note">Design sample: email verification completes registration automatically; no Platform Admin approval.</small></div><div class="of-trial-number"><strong>10</strong><span>Employee seats</span><small>7 active · 1 pending · 2 available in this sample</small></div></div>
 <div class="of-three"><div class="of-card"><span class="of-step">01</span><h3>Register and verify email</h3><p>No manual Platform Admin approval. Verification creates an active Owner workspace.</p></div><div class="of-card"><span class="of-step">02</span><h3>Design the ceilings</h3><p>Start from Digital AI's six-domain standard. Set company, department and position targets.</p></div><div class="of-card"><span class="of-step">03</span><h3>Invite and measure</h3><p>Add Managers, then up to 10 Employees. A baseline test reveals current levels against each position's target.</p></div></div>
 <div class="of-trial-rules" id="trial-rules"><div><span class="of-kicker">ACCESS POLICY</span><h2>Clear rules from day one.</h2></div><div class="of-rule-list"><p><b>Basic:</b> six free courses, full lesson access and final assignment.</p><p><b>Higher levels:</b> outline visible; Owner purchases and assigns seats to open lessons.</p><p><b>Capacity:</b> 10 active or pending Employee invitations across every department.</p><p><b>Duration:</b> no trial expiry date. Email verification still protects account creation.</p></div></div>`}

function capSelect(scope,index,value,max,deptIndex=-1,positionIndex=-1){return `<select aria-label="${scope} ceiling for ${esc(DOMAINS[index])}" data-cap-scope="${scope}" data-domain="${index}" data-dept="${deptIndex}" data-position="${positionIndex}">${[0,1,2,3].map(n=>`<option value="${n}" ${n===value?'selected':''}>${n===0?'0 · Outside path':`L${n} · ${LEVELS[n]}`}${n>max?' · above parent':''}</option>`).join('')}</select>`}
function capMatrix(){const d=dept(),p=position();return `<div class="of-cap-table"><div class="of-cap-table-head"><span>DOMAIN / COURSE FAMILY</span><span>DIGITAL AI</span><span>BUSINESS</span><span>${esc(d.name.toUpperCase())}</span><span>${esc(p.name.toUpperCase())}</span></div>${DOMAINS.map((name,i)=>`<div class="of-cap-row"><div><b>0${i+1}</b><strong>${name}</strong></div><span class="of-platform-cap">L3 <small>platform max</small></span>${capSelect('enterprise',i,model.enterprise[i],3)}${capSelect('department',i,d.caps[i],model.enterprise[i],model.selectedDept)}${capSelect('position',i,p.targets[i],d.caps[i],model.selectedDept,model.selectedPosition)}</div>`).join('')}</div>`}
function setupForms(){return `<div class="of-two of-structure-forms"><form class="of-card" id="of-department-form"><span class="of-kicker">ADD A DEPARTMENT</span><h3>Start with a team and its first position.</h3><div class="of-structure-fields"><label>Department<input name="department" required placeholder="Customer Success"></label><label>First position<input name="position" required placeholder="Support Specialist"></label><button class="of-button secondary" type="submit">Add department</button></div></form><form class="of-card" id="of-position-form"><span class="of-kicker">ADD A POSITION TO ${esc(dept().name.toUpperCase())}</span><h3>One team can have different targets.</h3><div class="of-structure-fields"><label>Position title<input name="position" required placeholder="Senior Accountant"></label><button class="of-button secondary" type="submit">Add position</button></div></form></div>`}
function proposalCard(){const pending=model.proposals.filter(p=>p.status==='pending');return `<div class="of-card of-proposal"><div class="of-card-title"><div><span class="of-kicker">MANAGER SUGGESTIONS</span><h3>Owner keeps the final decision.</h3></div>${badge(`${pending.length} pending`,pending.length?'coral':'lime')}</div>${pending.length?pending.map(p=>`<div class="of-proposal-row"><div><strong>${esc(p.dept)} · ${p.type==='position'?`${esc(p.position)} · `:''}${esc(SHORT[p.domain])}</strong><p>${esc(p.by)} suggests ${p.type==='position'?'position target':'department ceiling'} L${p.requested}. ${esc(p.reason)}</p></div><div class="of-proposal-actions">${button('Accept','accept-proposal','secondary',`data-id="${p.id}"`)}${button('Decline','decline-proposal','quiet',`data-id="${p.id}"`)}</div></div>`).join(''):'<p>No proposal needs review. Managers can still suggest changes without editing ceilings directly.'}</div>`}
function blueprintPage(){const d=dept();return `${heading('02 / OWNER · CAPABILITY BLUEPRINT','Design a path your business actually needs.','Choose company ceilings first, then department ceilings, then position targets. Every choice is compared with the shared Digital AI standard.',badge(model.dirty?'UNPUBLISHED CHANGES':model.published?'PUBLISHED SAMPLE':'DRAFT',model.dirty?'coral':'lime'))}
 <div class="of-sequence"><span><b>01</b> Digital AI standard</span><i>→</i><span><b>02</b> Business ceiling</span><i>→</i><span><b>03</b> Department ceiling</span><i>→</i><span><b>04</b> Position target</span></div>
 <div class="of-blueprint-controls"><div><label for="of-dept">Department</label><select id="of-dept" data-select="department">${model.departments.map((x,i)=>`<option value="${i}" ${i===model.selectedDept?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div><label for="of-position">Position within ${esc(d.name)}</label><select id="of-position" data-select="position">${d.positions.map((x,i)=>`<option value="${i}" ${i===model.selectedPosition?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="of-control-tip">One department may have several positions. The department gives a default scope; the position gives each Employee an exact target.</div></div>
 ${setupForms()}
 <div class="of-card of-matrix-card"><div class="of-card-title"><div><span class="of-kicker">SIX DOMAINS × THREE LEVELS</span><h2>The ceiling editor</h2></div><span class="of-formula">Position ≤ Department ≤ Business ≤ Digital AI</span></div><p class="of-matrix-hint">Scroll sideways on small screens to compare all four layers →</p><div class="of-matrix-scroll">${capMatrix()}</div><div class="of-matrix-footer"><span>Changing a parent ceiling cannot silently lower a department or position target.</span>${button('Publish blueprint','publish')}</div></div>
 <div class="of-two of-after-matrix"><div class="of-card of-soft"><span class="of-kicker">SETUP GATE</span><h3>Publish before people enter the path.</h3><p>After the blueprint is published, the Owner creates Managers and invites Employees. Their baseline tests then compare current levels with the targets set here.</p>${button('Go to people setup →','people','secondary')}</div>${proposalCard()}</div><div class="of-card of-policy-editor"><div><span class="of-kicker">COURSE ASSIGNMENT POLICY · OWNER CONFIGURES</span><h3>Give the second submission a fair window.</h3><p>The learner gets two total submissions. After a first fail, focused review precedes the final submission. Both a waiting period and a deadline apply. These time values are editable samples; the exact values still need your decision.</p></div><div class="of-policy-fields"><label>Wait before attempt 2<select data-policy="cooldown">${[24,48,72].map(x=>`<option value="${x}" ${x===model.cooldownHours?'selected':''}>${x} hours</option>`).join('')}</select></label><label>Deadline after opening<select data-policy="deadline">${[1,3,7,14].map(x=>`<option value="${x}" ${x===model.deadlineDays?'selected':''}>${x} day${x===1?'':'s'}</option>`).join('')}</select></label></div></div>`}

function peoplePage(){const d=dept(),available=10-assignedCount();return `${heading('03 / OWNER · PEOPLE & ROUTING','Place each person on the right path.','Select the department first, then the position inside it. Managers see their own department; an Employee sees only courses that support the assigned position.',badge(`${assignedCount()} / 10 EMPLOYEE SEATS`,available?'blue':'coral'))}
 <div class="of-people-hero"><div><span class="of-kicker">SEQUENCE MATTERS</span><h2>Blueprint → Manager → Employee → Baseline test</h2><p>The department chooses the team and Manager. The position sets the precise competency targets. If a department has one position, the form can select it automatically.</p></div><div class="of-capacity"><strong>${available}</strong><span>Employee seats open</span><small>Manager and Owner accounts are outside this limit.</small></div></div>
 <div class="of-two"><div class="of-card"><div class="of-card-title"><div><span class="of-kicker">STEP 01 / MANAGER</span><h3>Assign a department Manager.</h3></div>${badge(model.published&&!model.dirty?'Blueprint ready':'Publish first',model.published&&!model.dirty?'lime':'coral')}</div><p>Accounting: ${esc(model.departments[0].manager)} · Marketing: ${esc(model.departments[1].manager)} · Sales: ${esc(model.departments[2].manager)}.</p><div class="of-inline-form"><input id="of-manager-name" aria-label="Manager name" placeholder="New Manager name"><select id="of-manager-dept" aria-label="Manager department">${model.departments.map((x,i)=>`<option value="${i}">${esc(x.name)}</option>`).join('')}</select>${button('Add Manager','add-manager','secondary')}</div></div><div class="of-card"><div class="of-card-title"><div><span class="of-kicker">STEP 02 / EMPLOYEE</span><h3>Invite into a position path.</h3></div>${badge(`${model.employees.length} active · ${model.pendingEmployees} pending`,'blue')}</div><form id="of-invite-form" class="of-invite-form"><label>Full name<input name="name" required placeholder="Taylor Nguyen"></label><label>Work email<input name="email" type="email" required placeholder="taylor@business.com"></label><label>Department<select name="department" id="of-invite-dept">${model.departments.map((x,i)=>`<option value="${i}" ${i===model.selectedDept?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Position<select name="position" id="of-invite-position">${d.positions.map((x,i)=>`<option value="${i}">${esc(x.name)}</option>`).join('')}</select></label><button class="of-button primary" type="submit" ${available<=0||model.dirty?'disabled':''}>Invite Employee ↗</button></form></div></div>
 <div class="of-card of-import"><div><span class="of-kicker">BULK IMPORT / CSV</span><h3>Preview every route before inviting.</h3><p>File columns: email, full_name, department, position, role. A row is blocked if its position belongs to another department or would exceed 10 Employee seats.</p><a href="assets/member-import-template.csv" download="member-import-template.csv">↓ Download sample CSV</a></div><label class="of-file-drop">Choose a CSV file<input type="file" id="of-import-file" accept=".csv,text/csv,text/plain"></label></div>${model.importRows?importPreview():''}
 <div class="of-roster"><div class="of-card-title"><div><span class="of-kicker">SAMPLE TEAM</span><h3>Every person has one department and position.</h3></div>${button('Compare current and target →','gap','secondary')}</div><div class="of-roster-grid">${model.employees.slice(0,6).map((x,i)=>`<button type="button" data-employee="${i}"><span class="of-avatar">${x.name.split(' ').map(w=>w[0]).join('')}</span><span><strong>${esc(x.name)}</strong><small>${esc(x.dept)} · ${esc(x.position)}</small></span><b>↗</b></button>`).join('')}</div></div>`}

function importPreview(){const rows=model.importRows||[],valid=rows.filter(r=>!r.errors.length),invalid=rows.length-valid.length,available=10-assignedCount();return `<div class="of-card of-import-results"><div class="of-card-title"><div><span class="of-kicker">CSV REVIEW · ${esc(model.importFilename)}</span><h3>${valid.length} ready · ${invalid} need a fix</h3></div>${badge(`${available} seats left`,'blue')}</div>${model.importError?`<p class="of-error">${esc(model.importError)}</p>`:''}<div class="of-import-table"><div class="of-import-head"><span>PERSON</span><span>DEPARTMENT → POSITION</span><span>CHECK</span></div>${rows.map(r=>`<div class="of-import-row"><span><strong>${esc(r.name||'—')}</strong><small>${esc(r.email||'—')}</small></span><span>${esc(r.dept||'—')} → ${esc(r.position||'—')}</span><span class="${r.errors.length?'of-bad':'of-good'}">${r.errors.length?esc(r.errors.join(' · ')):'Ready'}</span></div>`).join('')}</div><div class="of-import-foot"><p>${invalid?'Fix marked rows and re-upload.':'Every row fits the department path and trial capacity.'}</p>${button('Preview invitations','preview-import','secondary',invalid||!rows.length?'disabled':'')}</div></div>`}

function levelDots(current,target){return `<span class="of-level-dots" aria-hidden="true">${[1,2,3].map(n=>`<i class="${n<=current?'measured':n<=target?'desired':''}"></i>`).join('')}</span>`}
function comparisonRows(person){const targets=employeePosition(person)?.targets||[0,0,0,0,0,0],caps=employeeDept(person)?.caps||[0,0,0,0,0,0];return DOMAINS.map((name,i)=>{const current=person.current[i],target=targets[i],status=target===0?['Outside position path','muted']:current===0?['Not confirmed','pending']:current>=target?['At target','met']:[`Gap ${target-current}`,'gap'];return `<button class="of-gap-row ${i===model.selectedDomain?'active':''}" type="button" data-domain="${i}"><span class="of-domain-name"><b>0${i+1}</b><strong>${name}</strong></span><span class="of-current">${current?`L${current}`:'Pending'}<small>tested current</small></span><span class="of-gap-arrow">→</span><span class="of-desired">${target?`L${target}`:'—'}<small>position target</small></span>${levelDots(current,target)}<span class="of-gap-status ${status[1]}">${status[0]}</span><small class="of-cap-caption">Department ceiling L${caps[i]}</small></button>`}).join('')}
function pathDetail(person){const i=model.selectedDomain,target=employeePosition(person)?.targets[i]||0,current=person.current[i],cap=employeeDept(person)?.caps[i]||0;return `<div class="of-card of-path-detail"><span class="of-kicker">SELECTED / ${esc(DOMAINS[i].toUpperCase())}</span><h3>${esc(person.position)} path</h3><div class="of-current-target"><span><small>After baseline test</small><strong>${current?`L${current}`:'Pending'}</strong></span><b>→</b><span><small>Business wants</small><strong>${target?`L${target}`:'Not required'}</strong></span></div><p>Department ${esc(person.dept)} allows up to L${cap}. The position uses ${target?`L${target}`:'no target'} in this domain. ${current===0?'Complete the baseline test before calling this a confirmed gap.':target>current?`The measured gap is ${target-current} level${target-current===1?'':'s'}.`:'The current level meets this target.'}</p><div class="of-path-levels">${[1,2,3].map(n=>`<div class="${n>target?'outside':n<=current?'done':n===current+1?'next':'later'}"><span>0${n}</span><strong>${LEVELS[n]}</strong><small>${n===1?'Free Basic':'Paid seat'}${n>target?' · outside path':''}</small></div>`).join('')}</div>${button('Open employee learning →','employee-learning','secondary')}</div>`}
function gapPage(){const person=employee();const scope=model.gapScope;return `${heading('04 / SHARED VIEW · EMPLOYEE, MANAGER, OWNER','Current level beside the level we want.','A measured level comes from the baseline test or confirmed work. The position target comes from the published business blueprint; unconfirmed is never shown as a numeric gap.',badge(`${esc(person.dept)} · ${esc(person.position)}`,'blue'))}
 <div class="of-gap-toolbar">${embeddedFlow?`<span class="of-identity-note">${scope==='manager'?'Manager · '+esc(model.departments[model.managerDept].name):'Owner · business-wide'} view</span>`:`<div class="of-scope" role="group" aria-label="Preview by role">${[['employee','Employee'],['manager','Manager'],['owner','Owner']].map(([id,label])=>`<button type="button" class="${scope===id?'active':''}" data-scope="${id}">${label}</button>`).join('')}</div>`}${scope==='employee'?`<span class="of-identity-note">Personal view · ${esc(person.name)}</span>`:`<label>Person<select data-select="employee">${model.employees.map((x,i)=>({x,i})).filter(({x})=>scope==='owner'||x.dept===model.departments[model.managerDept].name).map(({x,i})=>`<option value="${i}" ${i===model.selectedEmployee?'selected':''}>${esc(x.name)} · ${esc(x.position)}</option>`).join('')}</select></label>`}</div>
 <div class="of-gap-summary"><div><span>MEASURED NOW</span><strong>${person.current.filter(x=>x>0).length}<small>/ 6 domains confirmed</small></strong></div><div><span>CONFIRMED GAPS</span><strong>${person.current.filter((x,i)=>x>0&&x<(employeePosition(person)?.targets[i]||0)).length}</strong></div><div><span>POSITION TARGET</span><strong>${employeePosition(person)?.targets.filter(x=>x>0).length||0}<small>/ 6 domains included</small></strong></div></div>
 <div class="of-two of-gap-layout"><div class="of-card"><div class="of-card-title"><div><span class="of-kicker">${scope==='employee'?'MY PATH':scope==='manager'?'MY TEAM':'ORGANIZATION CAPABILITY'}</span><h3>${esc(person.name)} · current → target</h3></div>${badge(esc(person.source),'lime')}</div><div class="of-gap-legend"><span><i class="measured"></i> Test confirmed</span><span><i class="desired"></i> Still to target</span><span><i></i> Outside target</span></div><div class="of-gap-rows">${comparisonRows(person)}</div></div>${pathDetail(person)}</div>
 <div class="of-bottom-note"><strong>Routing rule:</strong> Department picks the team and ceiling; position picks the exact target and courses. A one-position department auto-selects its position. Manager sees only their own department; Owner sees the whole business.</div>`}

function assignmentStatus(){const a=model.assignment;if(a.status==='ready')return ['Ready after learning','lime'];if(a.status==='pending')return [`Attempt ${a.attempts} / 2 · awaiting Manager`,'blue'];if(a.status==='cooldown')return [`Retry opens in ${hoursLeft(a.releaseAt)}h`,'coral'];if(a.status==='retryReady')return ['Attempt 2 / 2 · ready to submit','coral'];if(a.status==='approved')return ['Passed · course confirmed','lime'];return ['Needs support · Manager flagged','coral']}
function learningPage(){const a=model.assignment,[status,tone]=assignmentStatus();return `${heading('05 / EMPLOYEE · LEARN THE POSITION PATH','My Accounting path, from test to proof.','Mia sees Accounting → Accountant only. The current level and desired target stay visible while she studies Basic learning and submits a final assignment for that course.',badge('ACCOUNTING → ACCOUNTANT','blue'))}
 <div class="of-learning-hero"><div><span class="of-kicker">MIA / DATA & INFORMATION</span><h2>Current L1 <b>→</b> Accountant target L3</h2><p>Basic is free to read and study in full. Intermediate and Advanced stay visible as future steps and open only when purchased and assigned.</p><div class="of-hero-actions">${button('See the capability comparison','gap','secondary')}${button('Open sample lesson ↗','lesson','primary')}</div></div><img src="assets/learning-journey-abstract.png" alt="Abstract blue glass learning path"></div>
 <div class="of-learning-path"><div class="of-learning-step current"><span>01 · FREE BASIC</span><h3>Data and information</h3><p>Lessons and short checks completed in this example. The final course assignment is the last gate.</p>${badge(status,tone)}</div><div class="of-learning-step"><span>02 · PAID SEAT</span><h3>Intermediate</h3><p>Visible in Mia's Accountant path. Owner purchase and seat assignment are needed before lessons open.</p>${badge('Locked until access','gray')}</div><div class="of-learning-step"><span>03 · PAID SEAT</span><h3>Advanced</h3><p>Opens after the previous level is confirmed and a seat is assigned.</p>${badge('Future step','gray')}</div></div>
 <div class="of-two of-learning-lower"><div class="of-card"><div class="of-card-title"><div><span class="of-kicker">FINAL ASSIGNMENT / EACH COURSE</span><h3>Build a traceable tracking report.</h3></div>${badge(`${a.attempts} / 2 submissions used`,a.attempts?'coral':'blue')}</div><p>Submit a report with its data source, checkable calculation and a supported conclusion. A Manager evaluates this assignment after the course lessons and final check.</p><div class="of-criteria"><span><b>01</b> Traceable source</span><span><b>02</b> Checkable calculation</span><span><b>03</b> Supported conclusion</span></div>${a.status==='ready'||a.status==='retryReady'?`<form id="of-assignment-form"><label for="of-assignment-note">Your evidence note</label><textarea id="of-assignment-note" required placeholder="Describe the source, calculation and what the result means..."></textarea><button class="of-button primary" type="submit">Submit attempt ${a.attempts+1} of 2 →</button></form>`:a.status==='cooldown'?`<div class="of-retry-rule"><strong>Study the feedback before trying again.</strong><p>The second submission opens in ${hoursLeft(a.releaseAt)} hours and is due within ${model.deadlineDays} days after opening. One submission remains.</p>${button('Preview after waiting period','advance-time','secondary')}</div>`:a.status==='pending'?note('Your work is with the Manager. The next level remains locked until the final assignment is approved.'):a.status==='approved'?note('Manager approved this course. The next eligible level can open when your business has a seat.'):note('Two submissions did not meet the rubric. Your Manager sees a support flag and chooses coaching, a fresh learning cycle or a pause. No certificate is issued.')}</div>
 <div class="of-card of-feedback"><span class="of-kicker">MANAGER FEEDBACK & ATTEMPTS</span><h3>A clear path after every decision.</h3><div class="of-attempt-line"><span class="${a.attempts?'done':''}">01 First submission</span><i>→</i><span class="${a.attempts>1?'done':''}">02 Final submission</span><i>→</i><span class="${a.status==='approved'?'done':a.flagged?'flag':''}">${a.status==='approved'?'Passed':a.flagged?'Support flag':'Decision'}</span></div>${a.feedback?`<blockquote>“${esc(a.feedback)}”</blockquote>`:'<p>The Manager’s rubric decision and revision reason appear here, linked to this exact course assignment.</p>'}<div class="of-policy-mini"><strong>Two total submissions</strong><span>After the first fail: focused review, configured waiting period and a deadline. After the second fail: support flag.</span></div></div></div>`}

function queueItems(){return model.queue.filter(x=>x.dept===model.departments[model.managerDept].name)}
function selectedQueue(){return model.queue.find(x=>x.id===model.selectedSubmission)||model.queue[0]}
function queueStatus(item){if(item.id==='mia'){item.attempts=model.assignment.attempts;item.status=model.assignment.status;item.submitted=item.status==='pending'?'Just now':item.submitted}return item}
function reviewPage(){const d=model.departments[model.managerDept],items=queueItems().map(queueStatus),item=selectedQueue();const inScope=item.dept===d.name;return `${heading('06 / MANAGER · FINAL COURSE ASSIGNMENT','Grade the work after each course.','Short lesson checks are automatic. The final course assignment goes to the department Manager with its rubric and optional AI suggestions; the Manager makes the final pass or fail decision.',badge(`${esc(d.name)} MANAGER SCOPE`,'blue'))}
 <div class="of-review-toolbar">${embeddedFlow?`<span class="of-identity-note">${esc(d.name)} · ${esc(d.manager)}</span>`:`<label>Review as Manager of<select data-select="manager-department">${model.departments.map((x,i)=>`<option value="${i}" ${i===model.managerDept?'selected':''}>${esc(x.name)} · ${esc(x.manager)}</option>`).join('')}</select></label>`}${button('Propose a ceiling change','proposal','secondary')}</div>
 <div class="of-two of-review-layout"><div class="of-card"><div class="of-card-title"><div><span class="of-kicker">COURSE ASSIGNMENT QUEUE</span><h3>One review per learner, course and attempt.</h3></div>${badge(`${items.filter(x=>x.status==='pending').length} awaiting decision`,items.some(x=>x.status==='pending')?'coral':'lime')}</div><div class="of-queue">${items.map(x=>`<button type="button" class="${x.id===model.selectedSubmission?'active':''}" data-submission="${x.id}"><span class="of-queue-icon ${x.status==='flagged'?'flagged':''}">${x.status==='flagged'?'!':x.status==='pending'?'↗':'○'}</span><span><strong>${esc(x.employee)}</strong><small>${esc(x.course)} · Attempt ${x.attempts} / 2</small></span>${badge(x.status==='flagged'?'Support flag':x.status==='pending'?'Review now':x.status==='approved'?'Passed':x.status==='cooldown'?'Waiting':'Not submitted',x.status==='flagged'||x.status==='cooldown'?'coral':x.status==='approved'?'lime':'blue')}</button>`).join('')}</div><div class="of-manager-proposal"><span class="of-kicker">MANAGER CAN SUGGEST, OWNER CAN DECIDE</span><p>Propose a department ceiling or position target change with evidence. You cannot raise your department above the business ceiling.</p>${button('Write a proposal','proposal','secondary')}</div></div>
 <div class="of-card of-review-detail">${inScope?reviewDetail(item):`<span class="of-kicker">SELECT A PERSON IN ${esc(d.name.toUpperCase())}</span><h3>Only your department is visible.</h3><p>Choose a submission from your queue to read the evidence and rubric.</p>`}</div></div>`}
function courseReviewSample(item){if(item.course.startsWith('Digital content'))return {file:'accessible_campaign.pdf',detail:'Campaign artifact, image descriptions and source notes · sample',rubric:[['Accessible presentation','84','Images include meaningful descriptions.'],['Source attribution','62','Two visual sources need credits.'],['Audience fit','88','The format matches the channel.']]};if(item.course.startsWith('Communication'))return {file:'customer_message.pdf',detail:'Message, audience context and privacy check · sample',rubric:[['Audience and purpose','91','Purpose is clear for this audience.'],['Message clarity','75','Next action could be simpler.'],['Safe sharing','82','Private information is handled appropriately.']]};return {file:'tracking_report.xlsx',detail:'Source data, calculation and written conclusion · sample',rubric:[['Source traceability','90','Original report and date are linked.'],['Checkable calculation','70','Formula needs a clearer explanation.'],['Supported conclusion','80','Recommendation follows the figures.']]}}
function reviewDetail(item){if(item.status==='flagged')return `<span class="of-kicker">SUPPORT FLAG · TWO FAILED SUBMISSIONS</span><h3>${esc(item.employee)} needs a Manager decision.</h3><p>${esc(item.course)} did not meet the rubric after both allowed submissions. No certificate or next level is released.</p><div class="of-support-options"><span>Coach and reassign later</span><span>Start a fresh learning cycle</span><span>Pause the path</span></div>${button('Record support plan','support-plan','secondary')}`;
 if(item.status!=='pending')return `<span class="of-kicker">${esc(item.course.toUpperCase())}</span><h3>${esc(item.employee)} · ${item.status==='approved'?'passed':'not ready for review'}</h3><p>${item.status==='cooldown'?'The learner is in a timed review period. Their second submission is not open yet.':item.status==='ready'?'The employee completes the lessons and final check before the assignment can be submitted.':'The course decision is recorded.'}</p>`;
 const sample=courseReviewSample(item);return `<span class="of-kicker">${esc(item.course.toUpperCase())} · ATTEMPT ${item.attempts} / 2</span><h3>${esc(item.employee)} · evidence and rubric</h3><p>${esc(item.position)} · ${esc(item.dept)} · submitted ${esc(item.submitted)}. The Manager sees only work inside this department.</p><div class="of-evidence-file"><b>▤</b><span><strong>${sample.file}</strong><small>${sample.detail}</small></span>${badge('Ready to inspect','lime')}</div><div class="of-rubric-list">${sample.rubric.map(([criterion,score,detail])=>`<div><span><strong>${criterion}</strong><small>${detail}</small></span><b>${score}<small>/100 AI hint</small></b></div>`).join('')}</div><p class="of-ai-note">AI suggestions help locate evidence. They do not approve, reject or issue certificates. The Manager records the final decision and reason.</p><div class="of-decision"><div class="of-decision-switch">${[['pass','Pass'],['fail','Not yet']].map(([id,label])=>`<button type="button" data-decision="${id}" class="${model.decision===id?'active':''}">${label}</button>`).join('')}</div><label for="of-decision-reason">${model.decision==='fail'?'Specific reason and next step · required':'Comment for Employee · optional'}</label><textarea id="of-decision-reason" placeholder="Name the rubric criterion and the next action..."></textarea>${button('Record Manager decision','record-decision')}</div><div class="of-attempt-policy">${item.attempts===1?`If not yet: 1 final submission remains; wait ${model.cooldownHours}h, then submit within ${model.deadlineDays} days.`:'If not yet: 2 of 2 submissions used; flag for Manager support.'}</div>`}

function proposalDialog(){const d=model.departments[model.managerDept];return `<dialog id="of-proposal-dialog" class="of-dialog"><div class="of-dialog-head"><div><span class="of-kicker">MANAGER PROPOSAL</span><h2>Suggest a path change.</h2></div><button type="button" data-action="close-proposal" aria-label="Close">×</button></div><p>Your suggestion goes to the Owner. It does not change the published blueprint.</p><form id="of-proposal-form"><label>Department<input value="${esc(d.name)}" disabled></label><label>Change<select name="type"><option value="department">Department ceiling</option><option value="position">Position target</option></select></label><label>Position (for position target)<select name="position">${d.positions.map(x=>`<option value="${esc(x.name)}">${esc(x.name)}</option>`).join('')}</select></label><label>Domain<select name="domain">${DOMAINS.map((x,i)=>`<option value="${i}">${esc(x)} · business max L${model.enterprise[i]}</option>`).join('')}</select></label><label>Suggested level<select name="level"><option value="1">L1 · Basic</option><option value="2">L2 · Intermediate</option><option value="3" selected>L3 · Advanced</option></select></label><label>Evidence / reason<textarea name="reason" required placeholder="What did the team results show?"></textarea></label><button class="of-button primary" type="submit">Send proposal to Owner</button></form></dialog>`}

function render(){const views={trial:trialPage,blueprint:blueprintPage,people:peoplePage,gap:gapPage,learning:learningPage,review:reviewPage};document.title=`DigiTalent Pulse · ${VIEWS.find(v=>v[0]===model.view)?.[2]||'Enterprise flow'}`;$('#app').innerHTML=frame(views[model.view]())+proposalDialog();const managerSummary=$('.of-inline-form')?.previousElementSibling;if(managerSummary)managerSummary.textContent=model.departments.map(d=>`${d.name}: ${d.manager}`).join(' · ');const importButton=$('[data-action="preview-import"]');if(importButton)importButton.textContent='Invite checked rows';const importCopy=$('.of-import p');if(importCopy)importCopy.textContent='File columns: email, full_name, department, position, role. Use EMPLOYEE rows here; each position must belong to its department, and all pending invitations count toward 10 Employee seats.';saveEmbeddedFlow();requestAnimationFrame(reportEmbeddedHeight)}
function setCap(scope,domain,value,deptIndex,positionIndex){const d=model.departments[deptIndex];if(scope==='enterprise'){const affected=model.departments.filter(x=>x.caps[domain]>value);if(affected.length){toast(`Lower ${SHORT[domain]} in ${affected.map(x=>x.name).join(', ')} before lowering the business ceiling.`);return false}model.enterprise[domain]=value}
 else if(scope==='department'){if(value>model.enterprise[domain]){toast(`Department L${value} exceeds the business ceiling L${model.enterprise[domain]} in ${SHORT[domain]}.`);return false}const affected=d.positions.filter(x=>x.targets[domain]>value);if(affected.length){toast(`Lower ${affected.map(x=>x.name).join(', ')} before lowering the department ceiling.`);return false}d.caps[domain]=value}
 else{if(value>d.caps[domain]){toast(`Position L${value} exceeds ${d.name}'s ceiling L${d.caps[domain]} in ${SHORT[domain]}.`);return false}d.positions[positionIndex].targets[domain]=value}
 model.dirty=true;refresh();return true}
function parseCsv(text){const source=String(text||'').replace(/^\uFEFF/,'');const first=(source.split(/\r?\n/,1)[0]||'');const count=sep=>(first.match(new RegExp(sep==='\t'?'\\t':sep===';'?';':',','g'))||[]).length;const sep=['\t',';',','].sort((a,b)=>count(b)-count(a))[0];let rows=[],cells=[],cell='',quoted=false;for(let i=0;i<source.length;i++){const ch=source[i];if(ch==='"'){if(quoted&&source[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===sep&&!quoted){cells.push(cell.trim());cell=''}else if((ch==='\n'||ch==='\r'&&source[i+1]!=='\n')&&!quoted){cells.push(cell.trim());if(cells.some(x=>x))rows.push(cells);cells=[];cell=''}else if(ch!=='\r')cell+=ch}if(cell||cells.length){cells.push(cell.trim());rows.push(cells)}if(quoted)throw Error('An open quote needs a closing quote.');const headers=rows.shift()?.map(x=>x.toLowerCase().replace(/\s+/g,'_'))||[];if(headers.slice(0,5).join(',')!=='email,full_name,department,position,role')throw Error('Use the template header: email,full_name,department,position,role.');const seen=new Set();return rows.map((r,i)=>{const [email='',name='',deptName='',positionName='',role='EMPLOYEE']=r,errors=[];const normalized=email.trim().toLowerCase(),dept=model.departments.find(d=>d.name.toLowerCase()===deptName.toLowerCase()),pos=dept?.positions.find(p=>p.name.toLowerCase()===positionName.toLowerCase());if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalized))errors.push('Invalid email');if(!name)errors.push('Name required');if(seen.has(normalized))errors.push('Duplicate email');seen.add(normalized);if(!dept)errors.push('Unknown department');if(dept&&!pos)errors.push('Position does not belong to department');if(role.toUpperCase()!=='EMPLOYEE'&&role.toUpperCase()!=='MANAGER')errors.push('Use EMPLOYEE or MANAGER');if(role.toUpperCase()==='EMPLOYEE'&&model.employees.length+model.pendingEmployees+rows.slice(0,i+1).filter(row=>(row[4]||'EMPLOYEE').toUpperCase()==='EMPLOYEE').length>10)errors.push('10 Employee seat limit');return {email:normalized,name,dept:deptName,position:positionName,role:role.toUpperCase(),errors}})}
function recordDecision(reason){const item=selectedQueue();if(item.status!=='pending')return toast('Select a submitted assignment first.');if(model.decision==='fail'&&!reason.trim())return toast('Write the rubric reason and next step before recording Not yet.');if(model.decision==='pass'){item.status='approved';if(item.id==='mia'){Object.assign(model.assignment,{status:'approved',feedback:reason.trim()||'The evidence meets all three criteria.',flagged:false})}}
 else if(item.attempts>=2){item.status='flagged';if(item.id==='mia'){Object.assign(model.assignment,{status:'flagged',feedback:reason.trim(),flagged:true})}}
 else{item.status='cooldown';if(item.id==='mia'){const releaseAt=now()+model.cooldownHours*3600000;Object.assign(model.assignment,{status:'cooldown',feedback:reason.trim(),releaseAt,dueAt:releaseAt+model.deadlineDays*86400000})}}
 toast('Sample Manager decision recorded.');refresh()}
function applyProposal(id,accept){const p=model.proposals.find(x=>x.id===id);if(!p)return;if(accept){const d=model.departments.find(x=>x.name===p.dept);if(!d)return toast('The department no longer exists.');if(p.type==='position'){const pos=d.positions.find(x=>x.name===p.position);if(!pos)return toast('The position no longer exists.');if(p.requested>d.caps[p.domain])return toast('Raise the department ceiling first. Position cannot exceed it.');pos.targets[p.domain]=p.requested}else{if(p.requested>model.enterprise[p.domain])return toast('Raise the business ceiling first. Department cannot exceed it.');if(p.requested<Math.max(...d.positions.map(x=>x.targets[p.domain])))return toast('Lower position targets first.');d.caps[p.domain]=p.requested}model.dirty=true}p.status=accept?'accepted':'declined';refresh();toast(accept?'Proposal accepted into an unpublished draft. Publish before invitations.':'Proposal declined; published blueprint stays unchanged.')}
function act(name,element){switch(name){case 'register':model.signupDone=true;navigate('blueprint');break;case 'rules':$('#trial-rules')?.scrollIntoView({behavior:'smooth'});break;case 'publish':model.published=true;model.dirty=false;refresh();toast('Sample blueprint published. Managers and Employees can now use it.');break;case 'people':navigate('people');break;case 'gap':navigate('gap');break;case 'employee-learning':if(embeddedFlow)window.parent.postMessage({type:'pulse-operating-open',url:'07-employee-learning-preview.html#EM-04'},'*');else location.href='07-employee-learning-preview.html#EM-04';break;case 'lesson':if(embeddedFlow)window.parent.postMessage({type:'pulse-operating-open',url:'08-employee-lesson-preview.html?course=data&lesson=1'},'*');else location.href='08-employee-lesson-preview.html?course=data&lesson=1';break;case 'proposal':$('#of-proposal-dialog').showModal();break;case 'close-proposal':$('#of-proposal-dialog').close();break;case 'accept-proposal':applyProposal(Number(element.dataset.id),true);break;case 'decline-proposal':applyProposal(Number(element.dataset.id),false);break;case 'add-manager':{if(model.dirty)return toast('Publish the blueprint before adding a Manager.');const name=$('#of-manager-name')?.value.trim(),index=Number($('#of-manager-dept')?.value);if(!name)return toast('Enter a Manager name.');model.departments[index].manager=name;model.managers.push(name);refresh();toast(`${name} now manages ${model.departments[index].name} in this preview.`);break}case 'preview-import':toast('CSV rows checked in the preview. No invitations were sent.');break;case 'advance-time':model.nowOffsetHours+=model.cooldownHours;model.assignment.status='retryReady';const q=model.queue.find(x=>x.id==='mia');q.status='retryReady';refresh();break;case 'support-plan':toast('Preview only: a Manager would record a coaching, restart or pause plan.');break;case 'record-decision':recordDecision($('#of-decision-reason')?.value||'');break}}
document.addEventListener('click',event=>{const view=event.target.closest('[data-view]');if(view){event.preventDefault();navigate(view.dataset.view);return}const employeeButton=event.target.closest('[data-employee]');if(employeeButton){model.selectedEmployee=Number(employeeButton.dataset.employee);navigate('gap');return}const domain=event.target.closest('[data-domain]');if(domain&&!domain.matches('select')){model.selectedDomain=Number(domain.dataset.domain);refresh();return}const submission=event.target.closest('[data-submission]');if(submission){model.selectedSubmission=submission.dataset.submission;refresh();return}const scope=event.target.closest('[data-scope]');if(scope){model.gapScope=scope.dataset.scope;refresh();return}const decision=event.target.closest('[data-decision]');if(decision){model.decision=decision.dataset.decision;const draft=$('#of-decision-reason')?.value||'';refresh();const field=$('#of-decision-reason');if(field)field.value=draft;return}const action=event.target.closest('[data-action]');if(action)act(action.dataset.action,action)});
document.addEventListener('change',event=>{const select=event.target;if(select.dataset.capScope){const ok=setCap(select.dataset.capScope,Number(select.dataset.domain),Number(select.value),Number(select.dataset.dept),Number(select.dataset.position));if(!ok)select.value=select.dataset.capScope==='enterprise'?model.enterprise[Number(select.dataset.domain)]:select.dataset.capScope==='department'?model.departments[Number(select.dataset.dept)].caps[Number(select.dataset.domain)]:model.departments[Number(select.dataset.dept)].positions[Number(select.dataset.position)].targets[Number(select.dataset.domain)];return}if(select.dataset.select==='department'){model.selectedDept=Number(select.value);model.selectedPosition=0;refresh();return}if(select.dataset.select==='position'){model.selectedPosition=Number(select.value);refresh();return}if(select.dataset.select==='employee'){model.selectedEmployee=Number(select.value);refresh();return}if(select.dataset.select==='manager-department'){model.managerDept=Number(select.value);model.selectedSubmission=queueItems()[0]?.id||'';refresh();return}if(select.id==='of-invite-dept'){const d=model.departments[Number(select.value)];$('#of-invite-position').innerHTML=d.positions.map((p,i)=>`<option value="${i}">${esc(p.name)}</option>`).join('');return}if(select.id==='of-import-file'&&select.files?.[0]){const file=select.files[0];if(file.size>2*1024*1024)return toast('Use a CSV under 2 MB.');file.text().then(text=>{try{model.importRows=parseCsv(text);model.importFilename=file.name;model.importError='';refresh()}catch(error){model.importRows=null;toast(error.message)}});return}});
document.addEventListener('submit',event=>{const form=event.target;if(form.id==='of-invite-form'){event.preventDefault();if(model.dirty)return toast('Publish the blueprint first.');if(assignedCount()>=10)return toast('All 10 Employee seats are in use across the business.');const data=new FormData(form),d=model.departments[Number(data.get('department'))],p=d?.positions[Number(data.get('position'))],name=String(data.get('name')||'').trim(),email=String(data.get('email')||'').trim();if(!d||!p||!name||!email)return toast('Choose a valid department and its position.');model.pendingEmployees++;refresh();toast(`${name} is invited to the ${d.name} / ${p.name} path in this preview.`);return}if(form.id==='of-assignment-form'){event.preventDefault();const note=String($('#of-assignment-note')?.value||'').trim();if(note.length<20)return toast('Explain the source, calculation and conclusion in at least 20 characters.');const a=model.assignment;if(!['ready','retryReady'].includes(a.status)||a.attempts>=2)return toast('This assignment is not open for submission.');if(a.status==='retryReady'&&a.dueAt&&now()>a.dueAt)return toast('The resubmission deadline has passed. Ask your Manager for support.');a.attempts++;a.status='pending';const q=model.queue.find(x=>x.id==='mia');q.attempts=a.attempts;q.status='pending';q.submitted='Just now';refresh();toast(`Attempt ${a.attempts} of 2 sent to ${model.departments[0].manager} for review (preview).`);return}if(form.id==='of-proposal-form'){event.preventDefault();const data=new FormData(form),domain=Number(data.get('domain')),requested=Number(data.get('level')),reason=String(data.get('reason')||'').trim(),d=model.departments[model.managerDept];if(!reason)return toast('Add evidence for the Owner.');if(requested>model.enterprise[domain])return toast('A department proposal cannot exceed the business ceiling.');model.proposals.push({id:Date.now(),dept:d.name,domain,requested,reason,by:d.manager,status:'pending'});$('#of-proposal-dialog').close();refresh();toast('Proposal sent to Owner in this preview.');return}});
document.addEventListener('change',event=>{const select=event.target;if(!select.dataset.policy)return;if(select.dataset.policy==='cooldown')model.cooldownHours=Number(select.value);else model.deadlineDays=Number(select.value);model.dirty=true;refresh();toast('Assignment timing changed in the draft. Publish the blueprint to apply it.')});
document.addEventListener('submit',event=>{if(event.target.id!=='of-register-form')return;event.preventDefault();model.signupDone=true;navigate('blueprint');toast('Preview workspace created after email verification. No approval queue.')});
document.addEventListener('submit',event=>{const form=event.target;if(!['of-department-form','of-position-form'].includes(form.id))return;event.preventDefault();const data=new FormData(form),name=String(data.get('position')||'').trim();if(!name)return toast('Enter a position title.');if(form.id==='of-department-form'){const departmentName=String(data.get('department')||'').trim();if(!departmentName)return toast('Enter a department name.');if(model.departments.some(x=>x.name.toLowerCase()===departmentName.toLowerCase()))return toast('That department already exists.');const defaults=model.enterprise.map(x=>Math.min(x,1));model.departments.push(makeDept(departmentName,[...defaults],[{name,targets:[...defaults]}],'Unassigned'));model.selectedDept=model.departments.length-1;model.selectedPosition=0;model.dirty=true;refresh();toast(`${departmentName} added to the draft. Assign a Manager after publishing.`)}else{const d=dept();if(d.positions.some(x=>x.name.toLowerCase()===name.toLowerCase()))return toast('That position already exists in this department.');d.positions.push({name,targets:[...d.caps]});model.selectedPosition=d.positions.length-1;model.dirty=true;refresh();toast(`${name} added to ${d.name}; adjust its targets and publish.`)}});
document.addEventListener('submit',event=>{if(event.target.id!=='of-proposal-form')return;event.preventDefault();event.stopImmediatePropagation();const data=new FormData(event.target),d=model.departments[model.managerDept],domain=Number(data.get('domain')),requested=Number(data.get('level')),type=String(data.get('type')),positionName=String(data.get('position')||''),reason=String(data.get('reason')||'').trim();if(!reason)return toast('Add evidence for the Owner.');const parent=type==='position'?d.caps[domain]:model.enterprise[domain];if(requested>parent)return toast(`${type==='position'?'Position':'Department'} L${requested} exceeds its parent L${parent}.`);model.proposals.push({id:Date.now(),type,position:type==='position'?positionName:null,dept:d.name,domain,requested,reason,by:d.manager,status:'pending'});$('#of-proposal-dialog').close();refresh();toast('Proposal sent to Owner in this preview.')},true);
document.addEventListener('submit',event=>{if(event.target.id!=='of-invite-form')return;const data=new FormData(event.target),d=model.departments[Number(data.get('department'))],email=String(data.get('email')||'').trim().toLowerCase();if(d?.manager==='Unassigned'){event.preventDefault();event.stopImmediatePropagation();return toast(`Assign a Manager to ${d.name} before inviting Employees.`)}if(model.employees.some(x=>x.email.toLowerCase()===email)||model.pendingEmails.includes(email)){event.preventDefault();event.stopImmediatePropagation();return toast('This work email already has an active or pending Employee invitation.')}if(!model.dirty&&assignedCount()<10&&email)model.pendingEmails.push(email)},true);
document.addEventListener('click',event=>{const action=event.target.closest('[data-action="preview-import"]');if(!action)return;event.preventDefault();event.stopImmediatePropagation();const rows=model.importRows||[];if(model.dirty)return toast('Publish the blueprint before inviting people.');if(!rows.length||rows.some(r=>r.errors.length))return toast('Fix marked CSV rows first.');if(rows.some(r=>r.role!=='EMPLOYEE'))return toast('This CSV import accepts Employee rows. Add Managers in step 01.');if(rows.length>10-assignedCount())return toast('These rows exceed the 10 Employee seat limit.');if(rows.some(r=>model.departments.find(d=>d.name.toLowerCase()===r.dept.toLowerCase())?.manager==='Unassigned'))return toast('Assign a Manager to each department first.');const existing=new Set([...model.employees.map(e=>e.email.toLowerCase()),...model.pendingEmails]);if(rows.some(r=>existing.has(r.email)))return toast('A CSV email already has an active or pending Employee invitation.');model.pendingEmployees+=rows.length;model.pendingEmails.push(...rows.map(r=>r.email));model.importRows=null;refresh();toast(`${rows.length} Employee invitations added to the sample queue.`)},true);
document.addEventListener('click',event=>{const scope=event.target.closest('[data-scope]');if(!scope)return;event.preventDefault();event.stopImmediatePropagation();model.gapScope=scope.dataset.scope;if(model.gapScope==='manager'&&employee().dept!==model.departments[model.managerDept].name){const index=model.employees.findIndex(x=>x.dept===model.departments[model.managerDept].name);if(index>=0)model.selectedEmployee=index}refresh()},true);
window.addEventListener('message',event=>{if(!embeddedFlow||event.source!==window.parent||event.data?.type!=='pulse-operating-restore')return;const saved=event.data.state;if(saved&&Array.isArray(saved.departments)&&Array.isArray(saved.employees)){Object.assign(model,saved);model.view=VIEWS.some(v=>v[0]===location.hash.slice(1))?location.hash.slice(1):'trial';applyEmbeddedRole();render()}});
window.addEventListener('popstate',()=>{model.view=VIEWS.some(v=>v[0]===location.hash.slice(1))?location.hash.slice(1):'trial';render()});
document.addEventListener('DOMContentLoaded',()=>{restoreEmbeddedFlow();model.view=VIEWS.some(v=>v[0]===location.hash.slice(1))?location.hash.slice(1):'trial';if(embeddedFlow){document.body.classList.add('of-embedded');applyEmbeddedRole();new ResizeObserver(reportEmbeddedHeight).observe($('#app'))}render();if(embeddedFlow)window.parent.postMessage({type:'pulse-operating-ready'},'*')});
